INSERT INTO question_papers (id, slug, title, exam_type, focus_tags, question_count, difficulty, is_premium, sort_order, time_limit_minutes)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5719b83c-4f99-4f04-be3d-fec7f3a9ee3f', '4dd35f8a-98c9-47b0-b46c-4dfea9001f24', 0, 'A gap analysis — a formal, structured comparison between an organization''s CURRENT actual state and a DESIRED target state, specifically producing a prioritized list of the concrete gaps between the two that need to be closed, which then becomes the basis for a remediation roadmap; distinct from simply auditing compliance against a standard, since a gap analysis explicitly frames its output as the DELTA to close, not just a pass/fail compliance verdict.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('656d3524-2a7e-42e0-90db-39a130579540', '4dd35f8a-98c9-47b0-b46c-4dfea9001f24', 1, 'A tabletop exercise, since tabletop exercises are specifically defined as a formal comparison between an organization''s current security posture and a desired target state.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a7b59780-bffd-4e49-bf75-0dc6ced7ddd9', '4dd35f8a-98c9-47b0-b46c-4dfea9001f24', 2, 'A honeytoken, since honeytokens are the standard tool for comparing an organization''s current security posture against a desired target state.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a1f05366-be57-4bf7-afba-a2b060ebcaf9', '4dd35f8a-98c9-47b0-b46c-4dfea9001f24', 3, 'Organizations have no formal way to compare their current security posture against a desired target state; this can only ever be assessed informally with no structured process.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b32b9a56-e371-4f80-a4f6-f49e43d837bd', '34fe1746-f89b-49cc-b5d7-f5b9b635bb29', 0, 'Policy, standard, procedure, and guideline — a policy is a high-level, mandatory statement of intent set by leadership (WHAT must happen, not the specific technical detail); a standard is a specific, measurable, MANDATORY requirement that implements a policy''s intent (e.g., a required TLS version); a procedure is a detailed, step-by-step, repeatable set of instructions for carrying out a specific task; and a guideline is a RECOMMENDED (not mandatory) best practice — this hierarchy runs from most authoritative/general (policy) to most optional (guideline).');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c983fe45-f728-4b90-8ac7-4b8bef461524', '34fe1746-f89b-49cc-b5d7-f5b9b635bb29', 1, 'These four documents are functionally identical and interchangeable, with no meaningful hierarchy or distinction in authority or mandatory status between them.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e4c15178-7431-4c2c-8879-36e091e42f83', '34fe1746-f89b-49cc-b5d7-f5b9b635bb29', 2, 'A risk register, since risk registers are specifically defined as this four-tier hierarchy of policy, standard, procedure, and guideline documentation.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f2f2ddb4-33db-44f3-831f-9f687fb4c945', '34fe1746-f89b-49cc-b5d7-f5b9b635bb29', 3, 'A gap analysis, since gap analyses are specifically defined as the four-tier governance documentation hierarchy of policy, standard, procedure, and guideline.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('613f98a4-c5db-4edb-820d-247db138bf7d', '7fd196d3-ed01-49c6-85bf-65d50bc5a410', 0, 'A rootkit — malware that specifically modifies operating system components, often at the KERNEL level (the deepest, most privileged layer of the OS), specifically to hide its own presence — processes, files, network connections — from standard system tools and many security products, since the compromised OS itself is being manipulated to lie about what''s actually running; this deep-level concealment is exactly what makes rootkits particularly difficult to detect through normal, OS-reported system inspection.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('72b8492a-9548-4cdf-b6d7-bc02ea460152', '7fd196d3-ed01-49c6-85bf-65d50bc5a410', 1, 'Ransomware, since ransomware is defined as malware that modifies kernel-level OS components specifically to hide its own presence from system tools.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e2939ef6-cfad-41a6-8ed5-72fddca68e83', '7fd196d3-ed01-49c6-85bf-65d50bc5a410', 2, 'A watering hole attack, since watering hole attacks are defined as malware that hides its presence by modifying operating system kernel-level components.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('34b1f747-35d8-4453-8ee7-f848757c7b93', '7fd196d3-ed01-49c6-85bf-65d50bc5a410', 3, 'No malware can modify operating system components in a way that hides its presence from the OS''s own reporting; this scenario describes a technical impossibility.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f825b7f5-c708-468d-866e-955b9604ac54', '83b3c4c6-cfac-4997-96ed-416ca4e0e2e5', 0, 'A logic bomb — malicious code deliberately embedded to remain dormant and inactive, causing no observable harm, until a SPECIFIC triggering condition is met (a particular date, a particular event, or the absence of an expected condition, like a specific employee''s continued active status), at which point it executes its malicious payload; this delayed, condition-triggered activation is the defining characteristic distinguishing it from malware that acts immediately upon initial compromise.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3b46b271-de0b-4d8a-8a56-6feb29ab8d29', '83b3c4c6-cfac-4997-96ed-416ca4e0e2e5', 1, 'A rootkit, since rootkits are defined as malicious code that remains dormant until a specific future date or triggering condition occurs.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('398f9101-85a6-4598-a2fa-b5ff59157ec1', '83b3c4c6-cfac-4997-96ed-416ca4e0e2e5', 2, 'Steganography, since steganography is defined as malicious code that lies dormant until a specific date or triggering condition before executing a harmful payload.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('af5a436c-a8c9-4b79-8ceb-f9fcd9b63ed3', '83b3c4c6-cfac-4997-96ed-416ca4e0e2e5', 3, 'Malicious code can never be configured to delay its execution until a future date or specific triggering condition; all malware always executes immediately upon initial compromise.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('91198453-5ad1-40a9-950a-60b4606e1ad3', '3ab85a8e-389d-42b9-ad4c-bb30d4489050', 0, 'DNS poisoning (also called DNS cache poisoning or DNS spoofing) — corrupting a DNS resolver''s cached records (or otherwise manipulating the DNS resolution process) so that a legitimate, correctly-typed domain name resolves to an ATTACKER-CONTROLLED IP address instead of the real one, silently redirecting victims to a malicious site even though they entered the correct domain name themselves, with no visible indication in the browser''s address bar that anything is wrong at the domain-name level.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('36961177-a313-4688-bc31-ae6e926eea9a', '3ab85a8e-389d-42b9-ad4c-bb30d4489050', 1, 'A logic bomb, since logic bombs are defined as corrupting a DNS resolver''s cached records to redirect a legitimate domain name to an attacker-controlled IP address.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('26e91410-8311-45b2-9917-25977f637277', '3ab85a8e-389d-42b9-ad4c-bb30d4489050', 2, 'Credential stuffing, since credential stuffing is defined as manipulating DNS resolution so a correctly-typed domain name resolves to a malicious IP address.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('721f5e86-de38-4db0-a511-f7f8810640e4', '3ab85a8e-389d-42b9-ad4c-bb30d4489050', 3, 'DNS resolution cannot be manipulated by an attacker under any circumstance; a correctly-typed, legitimate domain name will always resolve to its genuine, correct IP address.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f9f0611e-f283-4ee0-a53a-c423bdf1b814', '90c23db8-2260-4d8f-8229-a82e4293e682', 0, 'Baiting — a social engineering technique that specifically relies on a target''s CURIOSITY or greed, offering something enticing (a labeled USB drive, a "free" download, a too-good-to-be-true offer) as bait to lure the victim into taking an action (plugging in a device, clicking a link, downloading a file) that compromises their system, without the attacker needing to directly interact with or manipulate the victim through any conversation, phone call, or email exchange at all.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('684c107c-5c50-45ae-9924-6e94ac158a06', '90c23db8-2260-4d8f-8229-a82e4293e682', 1, 'Pretexting, since pretexting is defined as leaving a labeled physical device in a public location to be discovered and used by a curious victim, with no fabricated scenario or story involved.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9ad214e6-aad0-4174-b857-4025ae9318aa', '90c23db8-2260-4d8f-8229-a82e4293e682', 2, 'A supply chain attack, since supply chain attacks are defined as leaving a labeled USB drive in a public location to exploit a target''s curiosity.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('353dc356-52e5-43bd-ac7b-49aa6f6a5821', '90c23db8-2260-4d8f-8229-a82e4293e682', 3, 'This scenario is not a realistic attack vector, since no employee would ever plug an unknown USB drive found in a public location into a work computer.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f012062e-9278-49a3-b377-8dcd7f19af65', 'ef8d0677-b8bd-4326-be87-ba2826e7a24b', 0, 'Option A is BYOD (Bring Your Own Device) and option B is COPE (Corporate-Owned, Personally-Enabled); the key trade-off is control versus employee acceptance — BYOD gives the organization LESS control (the device is genuinely the employee''s own property, limiting how invasively security policy can be enforced, and raising real privacy tension since personal and work data coexist on one device) but is generally more readily accepted by employees, while COPE gives the organization full ownership and much stronger security control (the organization can enforce a stricter security posture on a device it actually owns) at the cost of additional procurement expense and reduced employee device choice.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e2c19051-2629-4f4d-91cc-253dc9568fff', 'ef8d0677-b8bd-4326-be87-ba2826e7a24b', 1, 'Option A is COPE and option B is BYOD, with COPE meaning employees use their own personally-owned devices and BYOD meaning the company purchases and fully owns the devices.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('656798fd-15d8-4f66-9c8b-f760f09a95f9', 'ef8d0677-b8bd-4326-be87-ba2826e7a24b', 2, 'BYOD and COPE are functionally identical deployment models with no meaningful difference in device ownership, organizational control, or security trade-offs.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7bc3829c-e491-4721-be4a-9ea95a77add0', 'ef8d0677-b8bd-4326-be87-ba2826e7a24b', 3, 'Organizations have no formal, named models for mobile device deployment; every company handles employee mobile device usage identically with no meaningful distinction.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dc0a3702-0e8c-4f6d-89d4-130ffe51870d', 'adcd0820-1f13-4bdd-be75-aa3ed60bed7b', 0, 'Replace insecure legacy protocols with their secure, encrypted equivalents — Telnet (plaintext remote administration) should be replaced with SSH (which encrypts the session, including any credentials transmitted), and SNMPv1 (plaintext, weak default authentication) should be replaced with SNMPv3 (which adds genuine authentication and encryption) — a standard, foundational secure-architecture practice of deliberately choosing protocol VERSIONS/variants that provide confidentiality and integrity in transit rather than continuing to use older, insecure defaults purely out of legacy habit or inertia.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b2d037ff-a612-412f-9ceb-1e048f89bcf6', 'adcd0820-1f13-4bdd-be75-aa3ed60bed7b', 1, 'Telnet and SNMPv1 already provide full encryption and strong authentication by default, so no protocol replacement or remediation is actually necessary in this scenario.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('56619c64-889f-4590-94f4-3fe510246b30', 'adcd0820-1f13-4bdd-be75-aa3ed60bed7b', 2, 'The correct remediation is to replace SSH with Telnet and SNMPv3 with SNMPv1, since the newer protocol versions are the ones that transmit data in plaintext.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('33e2c302-65ae-4013-9749-81210b46549b', 'adcd0820-1f13-4bdd-be75-aa3ed60bed7b', 3, 'No secure, encrypted alternative exists for either remote administration or network device monitoring; plaintext protocols are the only options available for these specific functions.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('040dd6d4-be8b-4232-bb09-c9c61463e10e', 'c815f8bf-04fe-4e51-865a-a55ae677c599', 0, 'A Faraday cage (or Faraday shielding applied to a room) — a conductive enclosure specifically designed to block electromagnetic signals from passing through it in either direction, preventing signals emanating from equipment inside from being detected/intercepted from outside the shielded space, and equally preventing external wireless signals (Wi-Fi, cellular, Bluetooth) from reaching devices inside — a specialized physical security control for environments with genuinely severe electromagnetic-emanation or wireless-isolation requirements.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b6984467-7038-4f43-a51d-7ab38acb76cc', 'c815f8bf-04fe-4e51-865a-a55ae677c599', 1, 'A mantrap, since mantraps are specifically designed to block electromagnetic signals from passing through a room''s walls in either direction.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('87160e82-9688-4cd9-ad5f-707b5e048fd5', 'c815f8bf-04fe-4e51-865a-a55ae677c599', 2, 'A bastion host, since bastion hosts are the standard physical measure for shielding a room against electromagnetic signal leakage and external wireless interference.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9f433047-5b18-4b9d-a9dd-893417b37843', 'c815f8bf-04fe-4e51-865a-a55ae677c599', 3, 'No physical measure exists to block electromagnetic signals from passing through a room''s walls; wireless and electromagnetic signals can never be physically contained or blocked.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('96bdca8e-193c-4a00-aacd-e7af6308ea15', '9fde2944-54e0-4669-8f3e-0742bf1da391', 0, 'Secure boot (and measured boot / attestation) — a boot-time integrity verification process where each component in the boot chain (firmware, bootloader, OS kernel) is cryptographically verified against a trusted, signed baseline BEFORE being allowed to execute, specifically catching unauthorized tampering (like a bootkit — a rootkit-style compromise specifically targeting the boot process itself) at the earliest possible point, before the OS is even fully running and before runtime-level tools like FIM would even have a chance to observe anything.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('624aec77-ad88-4afc-a394-21f156d20f0c', '9fde2944-54e0-4669-8f3e-0742bf1da391', 1, 'File Integrity Monitoring, since FIM is specifically defined as verifying the boot process at every system startup before the operating system has finished loading.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2fac2768-d52c-4400-b83e-1c430cf8aad7', '9fde2944-54e0-4669-8f3e-0742bf1da391', 2, 'A write blocker, since write blockers are the standard mechanism for cryptographically verifying firmware, bootloader, and OS components during system startup.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0185f58a-b4ab-4fbb-957c-fc9ceb831ca0', '9fde2944-54e0-4669-8f3e-0742bf1da391', 3, 'No mechanism exists to verify the integrity of the boot process; any tampering with firmware, bootloader, or OS startup components is always undetectable by design.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d753f355-5362-4553-9000-9f3cfae01d0f', 'e150e507-cfa7-47a4-ad46-78685bfb7904', 0, 'SAST (Static Application Security Testing) analyzes an application''s SOURCE CODE directly, without executing it, catching issues like hardcoded credentials or unsafe coding patterns early in development, before the code even runs; DAST (Dynamic Application Security Testing) tests the RUNNING application from the outside (similar to how an attacker would interact with it), catching runtime-manifesting vulnerabilities like injection flaws that static code analysis alone might miss — the two are complementary, catching different, overlapping-but-distinct categories of vulnerability at different pipeline stages.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('aa4a1480-706f-4c89-959e-618b44d26234', 'e150e507-cfa7-47a4-ad46-78685bfb7904', 1, 'DAST analyzes source code without executing it, while SAST tests only the running application from the outside — the reverse of the correct definitions.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ef75e0a2-e36d-4059-a2cc-c1f4fa316b81', 'e150e507-cfa7-47a4-ad46-78685bfb7904', 2, 'SAST and DAST are identical testing approaches that always catch the exact same vulnerabilities at the exact same pipeline stage, with no meaningful distinction between them.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('739a73d0-7a87-4d5a-acd6-98910d143124', 'e150e507-cfa7-47a4-ad46-78685bfb7904', 3, 'Automated security testing of application source code or running applications is not possible; all code security review must always be performed entirely manually.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b01b290d-dc46-43fd-9c30-5ae73fb84453', '584a21b4-930e-4496-8451-969714aeaef5', 0, 'Sandboxing — executing a suspicious file or process in an ISOLATED, tightly controlled environment specifically instrumented to closely observe its behavior (file system changes, network connections attempted, registry modifications), with the isolation ensuring that even a genuinely malicious payload cannot escape to affect real production systems or spread further, directly enabling safe behavioral analysis of an unknown threat before any decision is made about it.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('80e6ce2d-557b-433b-99ed-487d06853005', '584a21b4-930e-4496-8451-969714aeaef5', 1, 'A honeynet, since honeynets are specifically defined as an isolated environment for directly executing and observing a suspicious file''s behavior before a threat decision is made.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a638237c-4a98-475f-82a9-1b14f20e7e27', '584a21b4-930e-4496-8451-969714aeaef5', 2, 'A bastion host, since bastion hosts are the standard tool for safely executing and observing a suspicious file''s behavior in isolation.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('de1f1345-465b-4831-a776-b380ce77473c', '584a21b4-930e-4496-8451-969714aeaef5', 3, 'No safe way exists to observe a suspicious file''s actual behavior without risking infection of a real production system; any execution of unknown code is always equally risky regardless of environment.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8876a29c-20ec-45a7-8b16-6d9e6c66564f', 'abfb11ed-3a6f-4bc3-87b0-521c8417f7cf', 0, 'Network Access Control (NAC) — automatically evaluates a connecting device''s security posture (patch level, antivirus status, encryption status, and other configurable checks) against a defined policy BEFORE granting it full network access, and can automatically place a non-compliant device onto a restricted, quarantined network segment (often with limited access, such as only to a remediation server) rather than either blocking it outright or granting full trusted access to a device that doesn''t actually meet the required security posture.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2516463a-86b9-4b12-8f79-80fcb3ce4bc1', 'abfb11ed-3a6f-4bc3-87b0-521c8417f7cf', 1, 'A write blocker, since write blockers are the standard technology for evaluating a connecting device''s security posture before granting network access.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9b7d65be-6a9a-48ec-836d-69587f612d0e', 'abfb11ed-3a6f-4bc3-87b0-521c8417f7cf', 2, 'A honeytoken, since honeytokens automatically evaluate a connecting device''s patch level, antivirus status, and encryption status before granting network access.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('efa8e161-f7e9-430a-9e68-403125a77f4a', 'abfb11ed-3a6f-4bc3-87b0-521c8417f7cf', 3, 'No technology exists to automatically evaluate a device''s security posture before granting it network access; every connecting device must always be either fully trusted or fully blocked with no intermediate quarantine option.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b9d387cb-9a3d-4c27-b52b-ae59a3f6b399', '8b9eff6d-f635-4efa-803c-7191d4edd08d', 0, 'Threat modeling — a proactive, DESIGN-PHASE practice of systematically analyzing a planned system''s architecture to identify potential threats, attack paths, and entry points BEFORE the system is actually built, often using a structured methodology (like STRIDE, which categorizes threats into types such as Spoofing, Tampering, Repudiation, Information disclosure, Denial of service, and Elevation of privilege) — genuinely distinct from threat hunting (covered in a prior paper, a REACTIVE/investigative practice searching for evidence of an ALREADY-POSSIBLE compromise in an EXISTING, already-running environment).');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dcf6ef16-118f-41a7-9ec4-56fdb327db8d', '8b9eff6d-f635-4efa-803c-7191d4edd08d', 1, 'Threat hunting, since threat hunting is specifically defined as a design-phase practice performed before a system is built, rather than an investigative practice applied to an already-running environment.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('223ec55f-1ee0-44da-8fc3-f57de9bd3764', '8b9eff6d-f635-4efa-803c-7191d4edd08d', 2, 'A gap analysis, since gap analyses are specifically defined as systematically identifying potential attack paths and entry points in a system''s planned architecture before it is built.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('eb70476d-9dd2-4b13-ab7d-5e85a6f582d7', '8b9eff6d-f635-4efa-803c-7191d4edd08d', 3, 'Security considerations are never meaningfully incorporated into a system''s design phase; all security analysis can only happen after a system has already been fully built and deployed.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('40c50dd8-0291-4716-83b0-c2f34fd5c2f5', 'b9299301-5594-40d8-a1b4-e84b3c9e817c', 0, 'Red team (the attacking side, simulating a real adversary), blue team (the defending side, the organization''s own detection/response function), and purple team (a facilitating/coordinating role specifically focused on ensuring the red and blue teams actively share findings and lessons DURING the exercise, maximizing the exercise''s value as a learning/improvement activity for the defenders); this differs from a standard penetration test (covered in a prior paper), which typically evaluates ONLY whether vulnerabilities can be exploited, without necessarily also testing and improving the DEFENDING team''s real-time detection and response capability as a coordinated, dual-sided exercise.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e24e37f9-088d-43c4-89e6-c901649f6fc9', 'b9299301-5594-40d8-a1b4-e84b3c9e817c', 1, 'Blue team is the attacking side and red team is the defending side, the reverse of the correct definitions.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('55ae1350-a88d-45cf-aa9a-6b2ef48bdff5', 'b9299301-5594-40d8-a1b4-e84b3c9e817c', 2, 'Red team, blue team, and purple team are three different names for the exact same role, with no distinction between attacking, defending, or facilitating functions.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b6704048-2175-42d9-832e-91b775530473', 'b9299301-5594-40d8-a1b4-e84b3c9e817c', 3, 'A standard penetration test and a red team/blue team exercise are functionally and procedurally identical in every respect, with no meaningful distinction between them.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('24223e7d-3674-4894-b8d2-b75af4ce0494', '34948f1f-d28e-4fb7-8458-59a50790784c', 0, 'The fully-ready, near-real-time-replicated site is a HOT site, and the basic-infrastructure-only site is a COLD site; a WARM site (not directly described in this scenario) sits between the two — some hardware and partially current data already in place, but requiring meaningfully more setup time than a hot site to become fully operational, at correspondingly lower ongoing cost than a hot site but higher than a cold site.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6bb10bb7-bec7-48fb-8dc8-926b9bde7a4f', '34948f1f-d28e-4fb7-8458-59a50790784c', 1, 'The fully-ready, near-real-time-replicated site is a cold site, and the basic-infrastructure-only site is a hot site, the reverse of the correct definitions.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('95ecb117-03e1-4a26-b5f2-f99c3076add8', '34948f1f-d28e-4fb7-8458-59a50790784c', 2, 'Hot site and cold site are two different names for the exact same alternate-facility readiness level, with no meaningful difference in setup time or ongoing cost.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dd6d6574-8ecf-4e14-a173-86d6aee3f312', '34948f1f-d28e-4fb7-8458-59a50790784c', 3, 'Organizations have no standard, named classification for alternate processing site readiness levels; every alternate site is identical in setup time and cost.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f26e1034-2c7e-4f47-8020-078c98756e93', 'e9398de4-459c-4856-a6eb-8c364157f4fc', 0, 'Onboarding (specifically, security-focused pre-employment vetting) — background checks, employment/education verification, and signed agreements like an NDA performed BEFORE granting a new hire access to sensitive systems, specifically to establish a baseline of trust and legal accountability before that access is ever granted; this is the direct counterpart to offboarding (covered in a prior paper, which specifically revokes access at the END of employment) — together, proper onboarding and offboarding vetting/de-provisioning form the full security lifecycle bracketing an employee''s entire access to sensitive systems.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b3c428c2-1d43-4bde-b40b-7520a97ae6f5', 'e9398de4-459c-4856-a6eb-8c364157f4fc', 1, 'Offboarding, since offboarding is specifically defined as background checks and NDA signing performed before a new hire''s first day, rather than access revocation at employment''s end.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('70a466df-7d10-4652-826e-0564ee8255de', 'e9398de4-459c-4856-a6eb-8c364157f4fc', 2, 'A legal hold, since legal holds are the standard pre-employment process for background checks, employment verification, and NDA signing.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('76934945-6f48-4247-a9c8-cb36b237c6fc', 'e9398de4-459c-4856-a6eb-8c364157f4fc', 3, 'Pre-employment vetting of any kind provides no meaningful security value and is unrelated to protecting sensitive systems or data.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b0a66171-f9e6-4e41-a40c-44be120a351d', '3310891e-a2ec-4273-92eb-788c7c372946', 0, 'Data sovereignty (or data localization/residency) — a legal requirement that certain data must be physically stored (and sometimes also processed) WITHIN a specific country''s borders, governed by that country''s own laws regardless of the storing organization''s headquarters location; this is a genuinely different DIMENSION of data-protection law from GDPR''s extraterritorial reach (covered in a prior paper, which is about WHOSE data a law protects — EU residents'' — regardless of where the processing organization is based, not about WHERE the data must be physically stored).');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2ee0c715-5b20-40b7-bb3f-b0fefd0e12de', '3310891e-a2ec-4273-92eb-788c7c372946', 1, 'Data sovereignty and GDPR''s extraterritorial reach are the exact same legal concept describing the exact same requirement, with no meaningful distinction between them.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1882c715-bc27-41a4-a1a8-f3a809d2c8f3', '3310891e-a2ec-4273-92eb-788c7c372946', 2, 'A risk register, since risk registers are specifically defined as the legal requirement that certain data be physically stored within a specific country''s borders.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6f14b37f-2044-43f0-9d18-ba1cc9ecb24a', '3310891e-a2ec-4273-92eb-788c7c372946', 3, 'No country imposes any legal requirement regarding the physical geographic location where specific categories of data must be stored.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3a95801b-4221-4bf9-a814-ee5b28e88cec', '7f039762-5b00-4a92-b9ea-0e79d59b7f45', 0, 'The formal, binding uptime-and-penalty commitment is a Service Level Agreement (SLA) — a legally binding contract defining specific, measurable performance commitments (like uptime percentage) and typically specific consequences/penalties for failing to meet them; the informal, non-binding shared-understanding document is a Memorandum of Understanding (MOU) — expressing mutual intent and general understanding between parties WITHOUT the binding, legally enforceable specificity an SLA carries; a third type, a Business Partnership Agreement (BPA), formally defines the specific terms, responsibilities, and profit/liability-sharing arrangements of an actual ongoing business partnership, distinct from both.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b3d228e0-1d71-4b0a-bd33-badd433fdfd9', '7f039762-5b00-4a92-b9ea-0e79d59b7f45', 1, 'The formal, binding uptime-and-penalty commitment is an MOU, and the informal, non-binding shared-understanding document is an SLA, the reverse of the correct definitions.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d54af205-a891-4f88-b89a-702a0146d8f9', '7f039762-5b00-4a92-b9ea-0e79d59b7f45', 2, 'SLA and MOU are two different names for the exact same type of agreement, with no meaningful difference in binding legal force or specificity between them.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('575c59ce-cb7d-4028-bd21-574be034f8ac', '7f039762-5b00-4a92-b9ea-0e79d59b7f45', 3, 'Organizations have no standard, distinct agreement types for formalizing different kinds of inter-organizational relationships or commitments.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bec9e47b-a4da-4dd9-b929-26707c6fb6d4', 'f45e6f54-702f-4387-8e56-25097ca23da7', 0, 'Privacy by design — a principle holding that privacy protections (data minimization, encryption by default, user privacy controls) should be built into a system''s architecture from the very beginning of the design process, as a foundational consideration alongside functionality, rather than treated as an afterthought retrofitted onto an already-built system once a specific compliance requirement or incident forces the issue; several modern data protection regulations explicitly reference or require this principle.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e339b0f7-1d5e-4735-ba42-3ddc642dea16', 'f45e6f54-702f-4387-8e56-25097ca23da7', 1, 'A Data Protection Officer, since DPOs are specifically defined as the principle of building privacy protections into a system''s architecture from the beginning of the design process.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7a35ef69-4d62-4951-902a-316136eb4157', 'f45e6f54-702f-4387-8e56-25097ca23da7', 2, 'Data sovereignty, since data sovereignty is specifically defined as building privacy protections into an application''s architecture from the beginning of the design process.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6c5fe3a3-dd10-491b-80c8-d48826d0e320', 'f45e6f54-702f-4387-8e56-25097ca23da7', 3, 'Privacy considerations can only ever be meaningfully addressed after a system is already fully built and deployed, never incorporated during the initial design phase.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
